# R53: Songs' remaining routes (coverage.md wave 5), strings from inventory.md's SONGS section:
#   Explore     — Explore with its shelves, a public song (rating, Add to my library, Report), a shared song link
#   Groups      — Groups, Join with a link, New group, a group (invite link, shared folders, members), a shared folder
#   Folder      — a folder (Archived row), Folder settings, Card style, the folder's Archived
#   Archive     — Archive (Restore, Restore all, Delete) and Trash (Restore, Delete permanently, Empty Trash)
#   SongSettings — a song's Settings and Publish (Why publish, rights, published state, Unpublish)
#   Section     — a section's page (Chords, In time, One change at a time, Patterns, Practise)
# Exec'd by r41.py after r52_global.

def COV(t, c, w=56):
    return f'<span aria-hidden="true" style="flex: none; width: {w}px; height: {w}px; border-radius: {w // 6}px; background: {c}; box-shadow: inset 0 0 0 1px rgba(51,41,33,.08); display: flex; align-items: center; justify-content: center; font-family: {SERIF}; font-size: {w // 2.4:.0f}px; color: {INK}">𝄞</span>'
STAR = lambda fill: f'<svg viewBox="0 0 24 24" width="22" height="22" fill="{fill}" stroke="#C26A2E" stroke-width="1.6" stroke-linejoin="round" aria-hidden="true"><path d="m12 3 2.6 5.6 6 .7-4.5 4.1 1.2 6L12 16.4 6.7 19.4l1.2-6L3.4 9.3l6-.7z"></path></svg>'
def STRIP(lst='demo'):
    return (f'<div aria-label="Canvas: show a state" style="flex: none; margin: 0 12px 6px; padding: 6px; border-radius: 14px; border: 1.5px dashed {LINE}; display: flex; flex-wrap: wrap; gap: 6px; align-items: center"><span style="font-size: 12px; font-weight: 700; color: {SOFT}; padding: 0 4px">CANVAS · SHOW</span>'
            f'<sc-for list="{{{{{lst}}}}}" as="p" hint-placeholder-count="4"><button type="button" onClick="{{{{p.pick}}}}" style="height: 32px; padding: 0 10px; border: 0; border-radius: 16px; background: {{{{p.bg}}}}; color: {{{{p.fg}}}}; font: inherit; font-size: 13px; font-weight: 600">{{{{p.l}}}}</button></sc-for></div>')
EMPTY = lambda cond, icon, t, b, btns='': (f'<sc-if value="{{{{{cond}}}}}" hint-placeholder-val="{{{{false}}}}"><div style="display: flex; flex-direction: column; align-items: center; gap: 8px; padding: 56px 20px; text-align: center"><span style="width: 64px; height: 64px; border-radius: 32px; background: {FILL}; color: {SOFT}; font-size: 26px; display: flex; align-items: center; justify-content: center">{icon}</span>'
                                           f'<span style="font-size: 18px; font-weight: 700">{t}</span><span style="font-size: 15px; line-height: 1.45; color: {SOFT}; max-width: 340px">{b}</span>{btns}</div></sc-if>')
TOASTS = f'<sc-if value="{{{{toastOn}}}}" hint-placeholder-val="{{{{false}}}}"><div role="status" style="position: absolute; left: 16px; right: 16px; bottom: 40px; z-index: 56; min-height: 52px; border-radius: 14px; background: {INK}; color: {SHEET}; display: flex; align-items: center; gap: 8px; padding: 4px 4px 4px 16px; font-size: 15px"><span style="flex: 1">{{{{toastT}}}}</span><sc-if value="{{{{toastUndo}}}}" hint-placeholder-val="{{{{false}}}}"><button type="button" onClick="{{{{undo}}}}" style="height: 44px; padding: 0 12px; border: 0; background: transparent; color: {ACCENT}; font: inherit; font-size: 15px; font-weight: 700">Undo</button></sc-if></div></sc-if>'
TOASTL = TOASTS.replace('left: 16px; right: 16px; bottom: 40px', 'left: 50%; transform: translateX(-50%); width: 460px; bottom: 28px')
TOAST_JS = r'''
    const toast = (t, undo) => S({ toast: t, toastUndo: !!undo });
    if (st.toast && this._tt !== st.toast) { this._tt = st.toast; const t = st.toast; setTimeout(() => { if ((this.state || {}).toast === t) S({ toast: null }); this._tt = null; }, 2800); }
    const demoOf = (L, cur, key) => L.map((l) => ({ l, bg: cur === l ? '#332921' : '#EEE9E2', fg: cur === l ? '#FEFDFB' : '#332921', pick: () => S({ [key]: cur === l ? null : l }) }));'''
PAGEHEAD_L = lambda back_act, back_t, right='': (f'<header style="flex: none; height: 64px; display: flex; align-items: center; gap: 8px; padding: 0 28px 0 40px"><button type="button" onClick="{{{{{back_act}}}}}" style="height: 44px; margin-left: -12px; border: 0; background: transparent; color: {LINK}; font: inherit; font-size: 16px; font-weight: 600; display: flex; align-items: center; gap: 2px">{CHEV_L}{back_t}</button><span style="flex: 1"></span>{right}</header>')
WIDE = lambda inner, w=760: f'<main class="nos" style="flex: 1; min-height: 0; overflow-y: auto; padding: 0 56px 48px; display: flex; justify-content: center"><div style="width: {w}px; display: flex; flex-direction: column; gap: 16px">{inner}</div></main>'
NARROW = lambda inner: f'<main class="nos" style="flex: 1; min-height: 0; overflow-y: auto; padding: 8px 16px 48px; display: flex; flex-direction: column; gap: 16px">{inner}</main>'
H1 = lambda t: f'<h1 style="margin: 0; font-size: 30px; font-weight: 700; letter-spacing: -0.01em">{t}</h1>'
IF = lambda c, inner, h='false': f'<sc-if value="{{{{{c}}}}}" hint-placeholder-val="{{{{{h}}}}}">{inner}</sc-if>'

